const BASE_URL = process.env.REACT_APP_API_URL;

// 🔥 helper to get token
const getAuthHeader = () => {
  const token = localStorage.getItem("token");
  console.log("Using TOKEN:", token);
  return {
    Authorization: `Bearer ${token}`,
  };
};

export const bookAppointment = async (payload) => {
  try {
    const res = await fetch(`${BASE_URL}/book`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...getAuthHeader(),
      },
      body: JSON.stringify(payload),
    });

    console.log("BOOK APPOINTMENT STATUS:", res.status);

    if (!res.ok) {
      const text = await res.text();
      console.error("BOOK ERROR:", text);
      throw new Error("Booking failed");
    }

    return await res.json();
  } catch (err) {
    console.error("bookAppointment ERROR:", err);
    throw err;
  }
};



// 📌 Get logged-in user appointments
export const getMyAppointments = async () => {
  try {
    const res = await fetch(`${BASE_URL}/my`, {
      method: "GET",
      headers: {
        ...getAuthHeader(),
      },
    });

    console.log("GET /my STATUS:", res.status);

    if (!res.ok) {
      const text = await res.text();
      console.error("ERROR RESPONSE:", text);
      throw new Error("Failed to fetch appointments");
    }

    const data = await res.json();
    console.log("APPOINTMENTS DATA:", data);

    return data;
  } catch (err) {
    console.error("getMyAppointments ERROR:", err);
    throw err;
  }
};

// ❌ Cancel appointment
export const cancelAppointment = async (id) => {
  try {
    const res = await fetch(`${BASE_URL}/${id}/cancel`, {
      method: "PUT",
      headers: {
        ...getAuthHeader(),
      },
    });

    console.log("CANCEL STATUS:", res.status);

    if (!res.ok) {
      const text = await res.text();
      console.error("CANCEL ERROR:", text);
      throw new Error("Cancel failed");
    }

    const data = await res.json();
    console.log("CANCEL RESPONSE:", data);

    return data;
  } catch (err) {
    console.error("cancelAppointment ERROR:", err);
    throw err;
  }
};





export const getBookedSlots = async (doctorId, date) => {
  try {
    const res = await fetch(
      `${BASE_URL}/booked-slots?doctorId=${doctorId}&date=${date}`,
      {
        method: "GET",
        headers: {
          ...getAuthHeader(),
        },
      }
    );

    console.log("GET booked slots STATUS:", res.status);

    if (!res.ok) {
      const text = await res.text();
      console.error("BOOKED SLOTS ERROR:", text);
      throw new Error("Failed to fetch booked slots");
    }

    return await res.json();
  } catch (err) {
    console.error("getBookedSlots ERROR:", err);
    throw err;
  }
};
